20	PrimExpr BarrierBlocksOpNode::get_offset(const BufferLoadNode *load) const {
21	  PrimExpr offset = 0;
22	  PrimExpr stride = 1;
23	  auto buffer_shape = load->buffer->shape;
24	  for (int i = load->indices.size() - 1; i >= 0; i--) {
25	    offset += load->indices[i] * stride;
26	    stride *= buffer_shape[i];
27	  }
28	  return div(offset * load->dtype.bits(), 8);
29	}
