38	BarrierBlocksOp::BarrierBlocksOp(Array<PrimExpr> args,
39	                                 Map<String, ObjectRef> annotations) {
40	  ObjectPtr<BarrierBlocksOpNode> node =
41	      tvm::ffi::make_object<BarrierBlocksOpNode>();
42	  node->local_bar_addr = args[0];
43	  node->need_fence = bool(args[1].as<IntImmNode>()->value);
44	  const auto *call = node->local_bar_addr.as<CallNode>();
45	  ICHECK(call) << "local_bar_addr must be a call node";
46	  ICHECK(call->op.same_as(builtin::address_of()))
47	      << "local_bar_addr must be address_of op";
48	
49	  const auto *load = call->args[0].as<BufferLoadNode>();
50	  ICHECK(load) << "address_of argument must be a BufferLoad";
51	  node->offset = node->get_offset(load);
52	  node->local_bar = load->buffer;
53	  node->local_indices = load->indices;
54	  data_ = std::move(node);
55	}
56	
57	Stmt BarrierBlocksOpNode::Lower(const LowerArgs &T,
58	                                arith::Analyzer *analyzer) const {
59	  (void)analyzer;
60	  Array<PrimExpr> new_args;
61	  std::stringstream ss;
62	  ss << "tl::barrier_blocks";
63	  if (!need_fence) {
64	    ss << "<false>";
65	  }
66	  new_args.push_back(StringImm(ss.str()));
67	
68	  PrimExpr bar_addr = MakeLocalBarAddr(T);
69	  PrimExpr rank = Call(DataType::Int(64), tl::get_rank(), {});
70	  PrimExpr num_ranks = Call(DataType::Int(64), tl::get_num_ranks(), {});
71	  PrimExpr local_base_ptr =
72	      Call(DataType::Handle(), tl::get_remote_base_ptr(), {rank});
73	  PrimExpr offset_to_base =
74	      Sub(Call(DataType::Handle(), tl::get_uintptr_t(), {bar_addr}),
75	          local_base_ptr);
76	
77	  new_args.push_back(offset_to_base);
78	  new_args.push_back(rank);
79	  new_args.push_back(num_ranks);
80	
81	  auto barrier_blocks =
82	      Call(DataType::Handle(), builtin::call_extern(), new_args);
83	  return Evaluate(barrier_blocks);
84	}
