98	PrimExpr BarrierBlocksOpNode::MakeLocalBarAddr(const LowerArgs &T) const {
99	  const auto *call = local_bar_addr.as<CallNode>();
100	  ICHECK(call && call->op.same_as(builtin::address_of()))
101	      << "local_bar_addr must remain an address_of call";
102	  const auto *load = call->args[0].as<BufferLoadNode>();
103	  ICHECK(load) << "address_of must wrap a BufferLoad";
104	  Buffer buffer = load->buffer;
105	  if (T.buffer_remap.count(buffer)) {
106	    buffer = T.buffer_remap[buffer];
107	  }
108	  return Call(DataType::Handle(), builtin::address_of(),
109	              {BufferLoad(buffer, local_indices)});
110	}
