112	WaitOp::WaitOp(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
113	  ObjectPtr<WaitOpNode> node = tvm::ffi::make_object<WaitOpNode>();
114	  node->relation = args[0].as<IntImmNode>()->value;
115	  node->addr = args[1];
116	  node->expected = args[2];
117	  node->peer = args[3];
118	  data_ = std::move(node);
119	}
120	
121	bool WaitOpNode::is_distributed() const {
122	  return !(peer->IsInstance<IntImmNode>() &&
123	           peer.as<IntImmNode>()->value == -1);
124	}
125	
126	Stmt WaitOpNode::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
127	  (void)analyzer;
128	  (void)T;
129	  Array<PrimExpr> new_args;
130	  std::stringstream ss;
131	
132	  // Map relation as int to literal_strings
133	  const char *relation_str[] = {"eq", "ne", "ge", "le", "gt", "lt"};
134	  ss << "tl::wait_" << relation_str[relation];
135	
136	  new_args.push_back(StringImm(ss.str()));
137	  if (is_distributed()) {
138	    PrimExpr local_rank = Call(DataType::Int(64), tl::get_rank(), {});
139	    PrimExpr local_base_ptr =
140	        Call(DataType::Handle(), tl::get_remote_base_ptr(), {local_rank});
141	    PrimExpr offset_to_base = Sub(
142	        Call(DataType::Handle(), tl::get_uintptr_t(), {addr}), local_base_ptr);
143	    new_args.push_back(
144	        Call(DataType::Handle(), tl::get_remote_base_ptr(), {peer}) +
145	        offset_to_base);
146	  } else {
147	    new_args.push_back(addr);
148	  }
149	  new_args.push_back(expected);
150	
151	  auto wait = Call(DataType::Handle(), builtin::call_extern(), new_args);
152	  return Evaluate(wait);
153	}
