28	  PrimExpr offset = 0;
29	  PrimExpr stride = 1;
30	  auto buffer_shape = load->buffer->shape;
31	  for (int i = load->indices.size() - 1; i >= 0; i--) {
32	    offset += load->indices[i] * stride;
33	    stride *= buffer_shape[i];
34	  }
